#chat-view-title:focus{outline:none}
.page-heading[hidden]{display:none!important}
.socket-navigation{min-width:0}.socket-navigation>summary{display:flex;align-items:center;gap:11px;padding:11px 12px;border-radius:9px;font-size:13px;font-weight:600;color:#bac7d9;cursor:pointer;list-style:none}.socket-navigation>summary::-webkit-details-marker{display:none}.socket-navigation>summary:hover,.socket-navigation.is-active>summary{background:#29436b;color:#fff}.socket-nav-chevron{margin-left:auto;transition:transform .15s}.socket-navigation[open] .socket-nav-chevron{transform:rotate(180deg)}.socket-nav-links{display:grid;gap:3px;margin:7px 0 5px 21px;padding-left:10px;border-left:1px solid #3a4d68}.socket-nav-links a{padding:8px 10px;font-size:11px;gap:9px}.socket-nav-links a>span{color:#90a7ca;font:10px var(--mono);min-width:18px}.socket-nav-links a[aria-current=page]{background:#355989;color:#fff}.socket-navigation:focus-within>summary{color:#fff}
.chat-workspace [hidden]{display:none!important}.chat-heading{display:flex;justify-content:space-between;align-items:flex-start;gap:16px;margin-bottom:18px}.chat-heading h2{scroll-margin-top:90px;font-size:25px;letter-spacing:-.035em;margin:5px 0 8px}.chat-heading p{font-size:12px;line-height:1.6;color:#758297;margin:0;max-width:650px}.chat-breadcrumb{font-size:10px;color:#7387a6;font-weight:700;letter-spacing:.04em}.chat-heading-actions{display:flex;align-items:center;gap:10px;flex-shrink:0}.chat-workspace .panel{margin-bottom:16px}.chat-settings>summary,.chat-log-panel>summary,.chat-protocol>summary{cursor:pointer;padding:15px 18px;font-size:12px;font-weight:750;color:#354864;line-height:1.5}.chat-settings>summary small,.chat-log-panel>summary small{font-weight:400;color:#7d8da4;margin-left:8px}.chat-settings[open]>summary,.chat-log-panel[open]>summary{border-bottom:1px solid var(--line)}.chat-settings-grid{display:grid;grid-template-columns:1fr 1fr 1.2fr;gap:16px}.chat-workspace .field:last-child{margin-bottom:0}.chat-session-bar{padding:11px 15px;border:1px solid #dbe5f3;border-radius:10px;background:#eef4fd;color:#516887;font-size:11px;line-height:1.6;margin-bottom:18px;overflow-wrap:anywhere}.chat-step-intro h3{font-size:15px;margin:0 0 6px}.chat-step-intro p{font-size:12px;color:#77859b;line-height:1.7;margin:0;max-width:750px}.chat-actions{display:flex;align-items:center;flex-wrap:wrap;gap:9px;margin-top:18px}.chat-actions .btn{min-height:39px;padding:9px 14px}.chat-note{font-size:11px;line-height:1.7;color:#7687a0;margin:14px 0 0}.chat-note code{font:10px var(--mono);color:#456189}.chat-context-grid{display:grid;grid-template-columns:1fr 1fr;gap:16px}.chat-context-grid .field{margin-bottom:0}.chat-workspace .hint{font-size:10px;line-height:1.6;color:#7b8ca4}.chat-workspace .field textarea{min-height:100px}.chat-start-cards{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:13px;margin-top:18px}.chat-start-card{display:flex;gap:13px;text-decoration:none;padding:20px;background:white;border:1px solid var(--line);border-radius:12px;transition:background .15s,border-color .15s}.chat-start-card:hover{background:#f4f8ff;border-color:#a4bfe9}.chat-start-card>span{width:30px;height:30px;border-radius:9px;display:grid;place-items:center;background:#edf3ff;color:#3267c2;flex-shrink:0;font-size:12px;font-weight:800}.chat-start-card h3{font-size:13px;margin:0 0 6px}.chat-start-card p{font-size:11px;line-height:1.7;color:#7a899f;margin:0}.chat-next{display:flex;justify-content:space-between;gap:10px;margin:10px 0 18px}.chat-next a{font-size:11px;color:#3b6bb8;text-decoration:none;padding:6px 0}.chat-next a:hover{text-decoration:underline}.chat-result-grid{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1.15fr);gap:16px}.chat-code{white-space:pre-wrap;overflow-wrap:anywhere;max-height:350px;overflow:auto;background:#111f33;color:#d8e5f9;border-radius:9px;padding:16px;font:11px/1.7 var(--mono);margin:0;min-height:130px}.chat-result-heading{display:flex;align-items:center;justify-content:space-between;gap:10px;margin-bottom:12px}.chat-result-heading strong{font-size:12px}.chat-result-heading small{font-size:10px;color:#71829a}.chat-protocol summary{padding:0 0 12px;font-size:11px}.chat-listening{padding:14px;border:1px solid #d7e8df;border-radius:9px;background:#f3faf6;color:#396b50;font-size:12px;line-height:1.6;margin-top:16px}.chat-messages{display:grid;gap:10px;margin-top:12px;max-height:380px;overflow:auto}.chat-message{padding:13px 15px;border-radius:10px;background:#f2f6fc;border:1px solid #e1e9f5;white-space:pre-wrap;overflow-wrap:anywhere;font-size:12px;line-height:1.7}.chat-checklist{font-size:12px;line-height:1.9;padding-left:22px}.chat-send-choice{display:flex;align-items:flex-start;gap:9px;padding:13px 15px;background:#fff8ec;border:1px solid #f0dfb9;border-radius:9px;font-size:11px;color:#785f2e;line-height:1.6;margin-top:16px}.chat-send-choice input{margin-top:3px;accent-color:#bc8729}.chat-workspace .btn:disabled{cursor:not-allowed}.chat-workspace button:focus-visible,.socket-navigation summary:focus-visible,.socket-nav-links a:focus-visible,.chat-start-card:focus-visible{outline:3px solid #84abed;outline-offset:2px}
@media(max-width:1050px){.chat-settings-grid{grid-template-columns:1fr 1fr}.chat-settings-grid>.field:last-child{grid-column:1/-1}.chat-result-grid{grid-template-columns:1fr}}
@media(max-width:720px){.nav{flex-wrap:wrap;overflow:visible}.socket-navigation{flex:0 0 100%}.socket-nav-links{grid-template-columns:repeat(2,minmax(0,1fr));margin:4px 0 8px 8px}.socket-nav-links a{font-size:11px!important;white-space:normal}.chat-heading{flex-direction:column}.chat-heading h2{scroll-margin-top:90px;font-size:22px}.chat-settings-grid,.chat-context-grid,.chat-start-cards{grid-template-columns:1fr}.chat-settings-grid>.field:last-child{grid-column:auto}.chat-heading-actions{width:100%;justify-content:space-between}.chat-next{flex-wrap:wrap}.chat-actions .btn{flex:1 1 auto}.chat-result-grid{gap:12px}}

.socket-event-navigation>summary{cursor:pointer;padding:9px 10px;color:#bccde6;font-size:11px;font-weight:700}.socket-event-navigation a{margin-left:8px;font-size:10px}.socket-event-navigation{min-width:0}.chat-event-grid{display:grid;grid-template-columns:1fr 1fr;gap:14px}@media(max-width:720px){.chat-event-grid{grid-template-columns:1fr}}
